import{useEffect,useState}from'react';import type{ClientPluginContext,ViewProps}from'@aork/sdk/client';
function Home({runtime}:ViewProps){const[value,setValue]=useState('waiting');useEffect(()=>{let active=true;void runtime.query('fixture.cache',{cache:'prefer-cache'}).then(value=>{if(active)setValue('Cache '+value);}).catch(()=>{});return()=>{active=false;};},[runtime]);useEffect(()=>runtime.subscribe('fixture.stream',{next:()=>{}},{intervalMs:250}),[runtime]);return <h1>{value}</h1>;}
function Guard({runtime}:ViewProps){const[value,setValue]=useState('授权视图');const[complete,setComplete]=useState(false);return <section><h1>{value}</h1><output>{complete?'旧查询已结束':''}</output><button onClick={()=>{void runtime.query('workbench.overview').catch(()=>setComplete(true));}}>查询受保护内容</button><button onClick={()=>{void runtime.refreshAccess().then(()=>setValue('新授权已确认'));}}>检查新授权</button></section>;}
export function activate(context:ClientPluginContext){context.registerView('home',Home);context.registerView('guard',Guard);context.registerView('layout',({runtime})=><main>{runtime.renderView('aork.workbench.home@1')}{runtime.renderView('aork.auth.controls@1')}</main>);}
